#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "durbin.h"

/* Tuning parameter:
 *   Minimum number of iterations in the symmetric update loop
 *   before enabling OpenMP parallelization (if compiled with OpenMP).
 *   Can be adjusted for a given machine.
 */
#ifndef OMP_MIN_ITERS_DURBIN
# define OMP_MIN_ITERS_DURBIN 64
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      r[i] = (n+1-i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Local scalars. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

  /* Create local restrict-qualified pointers to help the compiler
     with alias analysis and enable better vectorization. The PolyBench
     harness always allocates r and y as distinct arrays, so this
     is semantically safe for this benchmark. */
  DATA_TYPE * __restrict r_ = r;
  DATA_TYPE * __restrict y_ = y;

#pragma scop
  /* Initialization of the recursion. */
  y_[0] = -r_[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r_[0];

  for (k = 1; k < _PB_N; k++) {
    /* Update beta: identical arithmetic expression as original. */
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

    /* Compute:
       sum = sum_{i=0}^{k-1} r[k-i-1] * y[i]

       We keep the accumulation strictly sequential to preserve the
       original floating‑point summation order. The only change is
       that we avoid recomputing (k-i-1) by maintaining a separate
       decreasing index j. */
    sum = SCALAR_VAL(0.0);
    {
      int j;
      for (i = 0, j = k - 1; i < k; i++, j--) {
        sum += r_[j] * y_[i];
      }
    }

    /* Same formula as in the original kernel. */
    alpha = - (r_[k] + sum) / beta;

    /* Original update:
         for (i = 0; i < k; i++)
           z[i] = y[i] + alpha * y[k-i-1];
         for (i = 0; i < k; i++)
           y[i] = z[i];

       Each new y[i] depends only on the *old* y[.] values; there is
       no true loop-carried dependency across i. We exploit this by
       doing an in-place symmetric update:

         new_y[i]       = y_old[i]       + alpha * y_old[k-1-i]
         new_y[k-1-i]   = y_old[k-1-i]   + alpha * y_old[i]

       handled in pairs (i, j = k-1-i). This removes the temporary
       array z[], roughly halving the y[] memory traffic while
       preserving per-element arithmetic expressions. */

    int half = k >> 1; /* floor(k/2) */

#if defined(_OPENMP)
    /* Parallelize the symmetric pair updates when there is
       enough work to amortize OpenMP overhead.  Each iteration
       writes y_[i] and y_[j] for a *unique* pair {i, j}, so
       there are no cross-iteration write conflicts. */
    if (half >= OMP_MIN_ITERS_DURBIN) {
#     pragma omp parallel for default(none) private(i) shared(y_, alpha, k, half)
      for (i = 0; i < half; i++) {
        int j = k - 1 - i;
        DATA_TYPE yi = y_[i];
        DATA_TYPE yj = y_[j];
        /* Same expressions as original:
             yi + alpha * yj
             yj + alpha * yi
           evaluated using the original (multiply then add) structure. */
        y_[i] = yi + alpha * yj;
        y_[j] = yj + alpha * yi;
      }
    } else
#endif
    {
      /* Sequential version of the same symmetric update. */
      for (i = 0; i < half; i++) {
        int j = k - 1 - i;
        DATA_TYPE yi = y_[i];
        DATA_TYPE yj = y_[j];
        y_[i] = yi + alpha * yj;
        y_[j] = yj + alpha * yi;
      }
    }

    /* If k is odd, there is a central element mid such that
       mid == k-1-mid; in the original code it is updated as:

         z[mid] = y[mid] + alpha * y[mid];
         y[mid] = z[mid];

       We reproduce exactly the same arithmetic expression,
       just without the temporary array. */
    if (k & 1) {
      int mid = half; /* For odd k, k = 2*half + 1. */
      DATA_TYPE ym = y_[mid];
      y_[mid] = ym + alpha * ym;
    }

    /* Set the new last element. */
    y_[k] = alpha;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_durbin (n,
		 POLYBENCH_ARRAY(r),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
