static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Local restrict-qualified pointers improve alias analysis and
   * give the compiler more freedom to keep data in registers and
   * vectorize inner loops.  POLYBENCH_1D parameters decay to
   * simple pointers here.
   */
  DATA_TYPE *restrict r_ptr = r;
  DATA_TYPE *restrict y_ptr = y;

  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int k;

#pragma scop
  /* Initial conditions of Durbin's recursion. */
  y_ptr[0] = -r_ptr[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r_ptr[0];

  for (k = 1; k < _PB_N; k++) {
    /* Update beta. Keeping the computation explicit helps the
     * compiler to keep intermediate values in registers.
     */
    beta *= (SCALAR_VAL(1.0) - alpha * alpha);

    /* Compute the inner product:
     *   sum = sum_{i=0}^{k-1} r[k-i-1] * y[i]
     * This loop is performance-critical (O(N^2)); the simple
     * structure is deliberate to help auto-vectorization.
     */
    sum = SCALAR_VAL(0.0);
    for (int i = 0; i < k; i++) {
      sum += r_ptr[k - i - 1] * y_ptr[i];
    }

    /* Update reflection coefficient alpha. */
    alpha = - (r_ptr[k] + sum) / beta;

    /* In-place symmetric update of y[0..k-1].
     *
     * Original code:
     *
     *   for (i = 0; i < k; i++)
     *     z[i] = y[i] + alpha * y[k - i - 1];
     *   for (i = 0; i < k; i++)
     *     y[i] = z[i];
     *
     * is equivalent to the following pairwise update:
     *
     *   let j = k - i - 1;
     *   y'[i] = y[i] + alpha * y[j];
     *   y'[j] = y[j] + alpha * y[i];
     *
     * For each pair (i, j) with i < j, we can compute y'[i] and
     * y'[j] in place using temporaries that hold the old values
     * of y[i] and y[j].  This removes the need for the temporary
     * array z[] and the extra copy-back loop, significantly
     * reducing memory traffic and improving cache locality while
     * preserving the exact mathematical result.
     */
    int i = 0;
    int j = k - 1;
    for (; i < j; ++i, --j) {
      const DATA_TYPE yi = y_ptr[i];
      const DATA_TYPE yj = y_ptr[j];
      y_ptr[i] = yi + alpha * yj;
      y_ptr[j] = yj + alpha * yi;
    }

