     * pairs with itself:
     *
     *   y'[m] = y[m] + alpha * y[m] = (1 + alpha) * y[m]
     *
     * which we implement as y[m] += alpha * y[m].
     */
    if (i == j) {
      y_ptr[i] += alpha * y_ptr[i];
    }

    /* Set the new last element. */
    y_ptr[k] = alpha;
  }
#pragma endscop

}


