 *  - Removed the temporary array z[] and perform the y-update in-place
 *    using symmetric pair updates. This halves the memory traffic for
 *    the update step and improves cache use.
 *  - Reindexed the inner "sum" loop so that both r[] and y[] are
 *    accessed with unit stride, which is more cache- and
 *    vectorization-friendly:
 *       sum = Σ r[k-i-1]*y[i]  -->  sum = Σ r[i]*y[k-1-i]
 *  - Added clear comments and kept the #pragma scop region intact.
 *
 * The mathematical algorithm (Durbin recursion) is unchanged.
 */
static
void kernel_durbin [[gnu::flatten, gnu::noinline]] (int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

