  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    const DATA_TYPE one = SCALAR_VAL(1.0);
    const int km1 = k - 1;

    /* Update beta: beta = (1 - alpha^2) * beta */
    beta = (one - alpha * alpha) * beta;

    /* Compute:
     *   sum = Σ_{i=0}^{k-1} r[k-1-i] * y[i]
     * Reindex to:
     *   sum = Σ_{i=0}^{k-1} r[i] * y[k-1-i]
     * This keeps both r and y accesses unit-stride, which improves
     * cache locality and allows efficient vectorization.
     */
    sum = SCALAR_VAL(0.0);
    for (i = 0; i < k; i++) {
      sum += r[i] * y[km1 - i];
    }

    /* Compute new reflection coefficient alpha. */
    alpha = -(r[k] + sum) / beta;

    /* In-place symmetric update of y[0..k-1].
     *
     * Original code:
     *   for (i = 0; i < k; i++)
     *     z[i] = y[i] + alpha * y[k-i-1];
     *   for (i = 0; i < k; i++)
     *     y[i] = z[i];
     *
     * Each new y[i] only depends on the old pair (y[i], y[k-1-i]),
     * so we can safely update y in-place using pairwise updates:
     *
     *   y[i]       <- y[i]       + alpha * y[j]
     *   y[j]       <- y[j]       + alpha * y[i]
     *   where j = k-1-i
     *
