      /* Update symmetric pairs (i, j=k-1-i). */
      for (i = 0; i < half; i++) {
        const int j = km1 - i;
        DATA_TYPE yi = y[i];
        DATA_TYPE yj = y[j];

        y[i] = yi + alpha * yj;
        y[j] = yj + alpha * yi;
      }

      /* If k is odd, handle the middle element that pairs with itself:
       *   y[m] <- y[m] + alpha * y[m] = (1 + alpha) * y[m]
       * where m = (k-1)/2 = half when k is odd.
       */
      if (k & 1) {
        const int mid = half;
        y[mid] = (one + alpha) * y[mid];
      }
    }

    /* Set the new element y[k] = alpha, as in the original algorithm. */
    y[k] = alpha;
  }
#pragma endscop
}


