#include "durbin.h"


/* Array initialization.
 *
 * Simple, contiguous traversal with a restrict-qualified pointer
 * to help the compiler optimize memory accesses.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i;
  DATA_TYPE * __restrict r_ptr = &r[0];

  for (i = 0; i < n; i++)
    {
      /* r[i] = n + 1 - i;  (cast via DATA_TYPE to avoid implicit conversions) */
      r_ptr[i] = (DATA_TYPE)(n + 1 - i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations compared to the reference version:
   - Removed the temporary array z[N] and perform the update of y[]
     in-place using symmetric pair updates. This cuts memory traffic
     for the core O(N^2) kernel roughly in half while preserving
     the exact mathematical computation.
   - Introduced local restrict-qualified pointers (r_ptr, y_ptr)
     to make aliasing relationships explicit to the compiler and
     improve vectorization and instruction scheduling.
   - Kept the order of floating-point operations in the reduction
     (sum) identical to the original implementation to preserve
     numerical behavior.
*/
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

  /* Local aliases with explicit non-aliasing semantics.
   * r and y never alias in this benchmark, so this is safe and
   * helps the optimizer.
   */
  DATA_TYPE * __restrict r_ptr = &r[0];
  DATA_TYPE * __restrict y_ptr = &y[0];

#pragma scop
  {
    /* Initial conditions.  Compute r[0] once and reuse. */
    const DATA_TYPE r0 = r_ptr[0];
    alpha    = -r0;
    y_ptr[0] = alpha;
    beta     = SCALAR_VAL(1.0);

    for (k = 1; k < _PB_N; ++k)
    {
      /* beta = (1 - alpha * alpha) * beta; */
      beta *= (SCALAR_VAL(1.0) - alpha * alpha);

      /* sum = Σ_{i=0}^{k-1} r[k - i - 1] * y[i]
       *
       * The loop below preserves the original accumulation order
       * over i = 0..k-1 (no reassociation), while using pointer
       * increments/decrements for efficient addressing.
       */
      sum = SCALAR_VAL(0.0);
      DATA_TYPE * __restrict r_k = r_ptr + (k - 1);
      DATA_TYPE * __restrict y_i = y_ptr;

      for (i = 0; i < k; ++i)
      {
        sum += (*r_k) * (*y_i);
        --r_k;
        ++y_i;
      }

      /* Update reflection coefficient alpha. */
      alpha = -(r_ptr[k] + sum) / beta;

      /* In-place symmetric update of y[0..k-1].
       *
       * Reference version:
       *   for (i = 0; i < k; i++)
       *     z[i] = y[i] + alpha * y[k-i-1];
       *   for (i = 0; i < k; i++)
       *     y[i] = z[i];
       *
       * which yields:
       *   y_new[i] = y_old[i] + alpha * y_old[k-i-1]
       *
       * We obtain the same result without an auxiliary array z
       * by updating symmetric index pairs (i, j = k-1-i)
       * simultaneously, using the old values saved in temporaries.
       */
      {
        const int half = k >> 1; /* floor(k / 2) */

        /* Handle symmetric pairs (i, j = k - 1 - i), i < j. */
        for (i = 0; i < half; ++i)
        {
          const int j = k - 1 - i;

          const DATA_TYPE y_i_old = y_ptr[i];
          const DATA_TYPE y_j_old = y_ptr[j];

          /* y_new[i] = y_old[i] + alpha * y_old[j]
           * y_new[j] = y_old[j] + alpha * y_old[i]
           */
          y_ptr[i] = y_i_old + alpha * y_j_old;
          y_ptr[j] = y_j_old + alpha * y_i_old;
        }

        /* If k is odd, there is a middle element mid = (k-1)/2
         * that maps to itself (j == i). For that element:
         *   y_new[mid] = y_old[mid] + alpha * y_old[mid]
         *               = (1 + alpha) * y_old[mid]
         */
        if (k & 1)
        {
          const int mid = half;
          const DATA_TYPE y_mid_old = y_ptr[mid];
          y_ptr[mid] = y_mid_old + alpha * y_mid_old;
        }
      }

      /* Final element for this stage of the recursion. */
      y_ptr[k] = alpha;
    }
  }
#pragma endscop

}


